{
  "shot": "static low-angle wide shot of the kitchen at dawn from <Picture 1>, camera about 45 cm above the oak floor, level, 24 mm perspective",
  "subject": {
    "who": "the woman from <Picture 1>, visible from the shoulders down, her face always out of frame",
    "outfit": "white semi-sheer blouse with black piping, slim black trousers, pointed black patent stiletto pumps",
    "prop": "clear plastic lunch box with a red apple and a green apple inside, held in her right hand"
  },
  "action": [
    { "time": "0-4 s", "beat": "she is already walking toward the right and continues with brisk, regular steps at the same pace, moving slightly toward the camera to pass in front of the cat feeder and its white bowl without touching them; the lunch box stays in her right hand and swings gently with each step" },
    { "time": "around 4 s", "beat": "her back heel leaves the frame through the right edge" },
    { "time": "4-10 s", "beat": "the kitchen is empty; fine dust drifts slowly in the golden sunbeams" }
  ],
  "camera": "static locked-off; the framing stays identical for the whole shot",
  "static_elements": "the oak drawers, the fridge, the cat feeder with its screen showing \"07:00\", the kibble, the white bowl, the rosemary pot and the balcony railing stay perfectly still, sharp and identical to <Picture 1>",
  "lighting": "low warm golden sunrise light from the balcony door on the right, backlighting her; her shadow moves across the oak drawers and the floorboards with her, then the drawers are fully lit; the light stays constant",
  "audio": {
    "ambience": "quiet morning room tone with a soft distant city hum",
    "sfx": [
      "close, crisp high-heel clicks on the wooden floor, one per step, fading as she exits right",
      "faint plastic rattle of the lunch box"
    ],
    "music": "none",
    "dialogue": "none"
  }
}
